 identity=sum(x['action']==x['predicted_action'] for x in rows);identity_by={a:sum(x['predicted_action']==a for x in rows if x['action']==a) for a in ACTIONS};confusion=Counter((x['action'],x['predicted_action']) for x in rows);assert identity==212 and identity_by=={'foreleg_rubbing':70,'head_directed_grooming':70,'reach_withdraw':72};assert confusion[('foreleg_rubbing','reach_withdraw')]==2 and confusion[('head_directed_grooming','reach_withdraw')]==2
